async newPage(options = {}) {
        return await this._wrapApiCall(async () => {
          const context2 = await this.newContext(options);
          const page = await context2.newPage();
          page._ownedContext = context2;
          context2._ownerPage = page;
          return page;
        }, { title: "Create page" });
      }

pageCloseSource:
async close(options = {}) {
        this._closeReason = options.reason;
        if (!options.runBeforeUnload)
          this._closeWasCalled = true;
        try {
          if (this._ownedContext)
            await this._ownedContext.close();
          else if (options.runBeforeUnload)
            await this._channel.runBeforeUnload({}, kNoTimeout);
          else
            await this._channel.close({ reason: options.reason }, kNoTimeout);
        } catch (e) {
          if (isTargetClosedError2(e) && !options.runBeforeUnload)
            return;
          throw e;
        }
      }
